import { expect, Page, Locator } from '@playwright/test';

export abstract class BasePage {
    public readonly page: Page;

    constructor(page: Page) {
        this.page = page;
    }

    public async navigate(url: string = '/') {
        await this.page.goto(url);
    }
}

import { expect, Page, Locator } from '@playwright/test';
import { BasePage } from './BasePage';

export class AmazonPage extends BasePage {
    public readonly searchInput: Locator = this.page.getByPlaceholder('Search Amazon');
    public readonly searchButton: Locator = this.page.getByRole('button', { name: 'Go' });
    public readonly cartIcon: Locator = this.page.locator('#nav-cart');
    public readonly navBar: Locator = this.page.locator('#nav-main');
    public readonly resultsContainer: Locator = this.page.locator('.s-main-slot');
    public readonly noResultsMessage: Locator = this.page.getByText('No results for');

    constructor(page: Page) {
        super(page);
    }

    public async performSearch(query: string) {
        await this.searchInput.fill(query);
        await this.searchButton.click();
    }
}

import { test, expect, Page } from '@playwright/test';
import { AmazonPage } from '../pages/AmazonPage';
import { EnvUtils } from '../utils/envUtils';
import testData from '../data/testData.json';

test.describe('Amazon Functionality Suite', () => {
    let amazonPage: AmazonPage;

    test.beforeEach(async ({ page }) => {
        amazonPage = new AmazonPage(page);
        await amazonPage.navigate(EnvUtils.BASE_URL);
    });

    test('TC-001 - Verify Amazon Homepage Elements Load Successfully', async () => {
        await expect(amazonPage.searchInput).toBeVisible();
        await expect(amazonPage.cartIcon).toBeVisible();
        await expect(amazonPage.navBar).toBeVisible();
    });

    testData.forEach((data) => {
        test(`${data.testCaseId} - ${data.description}`, async () => {
            await amazonPage.performSearch(data.query);

            if (data.testCaseId === 'TC-002') {
                await expect(amazonPage.resultsContainer).toBeVisible();
            } else if (data.testCaseId === 'TC-003') {
                await expect(amazonPage.page).toHaveURL(/.*amazon.com/);
            } else if (data.testCaseId === 'TC-004' || data.testCaseId === 'TC-005') {
                await expect(amazonPage.noResultsMessage).toBeVisible();
            }
        });
    });

    test('TC-006 - Verify Amazon Performance Under Simulated 3G', async ({ page, context }) => {
        const client = await context.newCDPSession(page);
        await client.send('Network.emulateNetworkConditions', {
            offline: false,
            downloadThroughput: 1.5 * 1024 * 1024 / 8, // 1.5 Mbps
            uploadThroughput: 750 * 1024 / 8,
            latency: 100
        });
        await page.reload();
        await expect(amazonPage.searchInput).toBeVisible();
        await expect(amazonPage.navBar).toBeVisible();
    });
});

